using EarthUnscripted.TerrainDraft;using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Diagnostics;using Clipper2Lib;using EarthUnscripted.TerrainDraft.AuthoringJson;
namespace EarthUnscripted.TerrainDraft.Core800 {
 public sealed class CoreCellWork {public readonly int X,Z;public readonly TerrainCellBounds Bounds;public TerrainFootprintUnionResult Union;public TerrainPoint[] SourceKnots,HardKnots;public Paths64 Band;public RoadCellFoundation Foundation;public double OriginY;public string Failure;public object Witness;public VerifiedJoinedTerrain Proof;public CoreCellWork(int x,int z,TerrainCellBounds bounds){X=x;Z=z;Bounds=bounds;}}
 public sealed class CoreCellPreparation {
  public const string Recipe="PantsideCore800/Global32PartialEdges/ContinuousGroup1/CanonicalFoundation-KernelFan/DerivedRoadBank1-v4";
  readonly DerivedRoadBank bank;
  readonly CoreSourceContext context;readonly RoadTerrainSource.QueryContext scratch;readonly Dictionary<PreciseTerrainBorderKey,SortedSet<double>> mandatory=new Dictionary<PreciseTerrainBorderKey,SortedSet<double>>();readonly Dictionary<PreciseTerrainBorderKey,LocalTerrainSeam> plans=new Dictionary<PreciseTerrainBorderKey,LocalTerrainSeam>();readonly LocalTerrainSeamPlanner planner=new LocalTerrainSeamPlanner(errorMetres:.0005);readonly Dictionary<(long,long),double> sampleCache=new Dictionary<(long,long),double>();readonly List<CoreCellWork> cells=new List<CoreCellWork>();public IReadOnlyList<CoreCellWork> Cells=>cells;public int BorderCount=>plans.Count;
  public CoreCellPreparation(CoreSourceContext input){context=input;bank=new DerivedRoadBank(input.Source);scratch=input.Source.NewQueryContext();for(int z=-13;z<=12;z++)for(int x=-13;x<=12;x++){var bounds=new TerrainCellBounds(Math.Max(-400,x*32),Math.Max(-400,z*32),Math.Min(400,(x+1)*32),Math.Min(400,(z+1)*32));cells.Add(new CoreCellWork(x,z,bounds));}}
  TerrainMeshSample Raw(double x,double z)=>context.Source.Height(x,z,scratch);
  double[] Origins(double x,double z)=>cells.Where(c=>x>=c.Bounds.MinX&&x<=c.Bounds.MaxX&&z>=c.Bounds.MinZ&&z<=c.Bounds.MaxZ).Select(c=>c.OriginY).Distinct().ToArray();
  bool Present(double x,double z)=>!context.Source.Pavement(x,z,out _,out _,out _);
  double CanonicalSample(double x,double z){long s=ManagedTerrainDomainLocal.Scale;var key=((long)Math.Round(x*s),(long)Math.Round(z*s));if(sampleCache.TryGetValue(key,out double y))return y;var raw=Raw(x,z);double value=raw.Y;var relevant=cells.Where(c=>c.Foundation!=null&&x>=c.Bounds.MinX&&x<=c.Bounds.MaxX&&z>=c.Bounds.MinZ&&z<=c.Bounds.MaxZ&&(x==c.Bounds.MinX||x==c.Bounds.MaxX||z==c.Bounds.MinZ||z==c.Bounds.MaxZ)).ToArray();bool foundationValue=false;foreach(var cell in relevant){try{value=cell.Foundation.BoundaryHeight(x,z);foundationValue=true;break;}catch(ArgumentException){}}if(!foundationValue&&raw.Authority==TerrainHeightAuthority.SourcePavement&&context.Source.Pavement(x,z,out _,out var owner,out _))value=context.Source.CanonicalSourceHeight(owner,x,z);var origins=Origins(x,z);if(origins.Length==0)throw new ArgumentException("Canonical borderpoint outside entire requestedcore");value=DoubleTerrainEmission.SharedHeight(value,origins);sampleCache.Add(key,value);return value;}
  PreciseSeamHeight Sample(double x,double z){var raw=Raw(x,z);return new PreciseSeamHeight(CanonicalSample(x,z),raw.SourceDistance);}
  void Knot(PreciseTerrainBorderKey key,double along){if(!mandatory.TryGetValue(key,out var set))mandatory[key]=set=new SortedSet<double>();set.Add(along);}
  public void PrepareAllBorders(CancellationToken cancellation=default){long scale=ManagedTerrainDomainLocal.Scale;foreach(var c in cells){cancellation.ThrowIfCancellationRequested();c.OriginY=Math.Round(Raw((c.Bounds.MinX+c.Bounds.MaxX)*.5,(c.Bounds.MinZ+c.Bounds.MaxZ)*.5).Y);}foreach(var c in cells){cancellation.ThrowIfCancellationRequested();try{var b=c.Bounds;var triangles=context.Source.SelectCell(c.X,c.Z,2.02).Where(t=>t.X0<=b.MaxX+2.02&&t.X1>=b.MinX-2.02&&t.Z0<=b.MaxZ+2.02&&t.Z1>=b.MinZ-2.02).ToArray();c.Union=BoundedTerrainFootprintUnion.Build(c.X,c.Z,triangles.Select(t=>t.Points).ToArray(),padding:2.02,token:cancellation,explicitBounds:b);if(c.Union.ZeroProjectedInputs>0)throw new ArgumentException("Positive source primitive collapses on declared4um lattice");c.SourceKnots=triangles.SelectMany(t=>t.Points).Distinct().ToArray();var hard=new List<TerrainPoint>();foreach(var p in c.Union.Contours.SelectMany(p=>p)){double x=b.MinX+(float)(p.X-b.MinX),z=b.MinZ+(float)(p.Z-b.MinZ);if(!context.Source.Pavement(x,z,out _,out var owner,out _))throw new ArgumentException("Exposed sourceboundary lacks original sourceplane");hard.Add(new TerrainPoint(x,(float)context.Source.CanonicalSourceHeight(owner,x,z),z));}c.HardKnots=hard.ToArray();var mask=new Paths64(c.Union.Contours.Select(r=>new Path64(r.Select(p=>new Point64((long)Math.Round(p.X*scale),(long)Math.Round(p.Z*scale))))));var rect=new Paths64{new Path64{P(b.MinX,b.MinZ),P(b.MaxX,b.MinZ),P(b.MaxX,b.MaxZ),P(b.MinX,b.MaxZ)}};var target=Clipper.Difference(rect,mask,FillRule.NonZero);c.Band=ManagedTerrainDensityBand.Build(mask,(long)Math.Round(b.MinX*scale),(long)Math.Round(b.MinZ*scale),4096);var empty=new ManagedTerrainMesh(Array.Empty<TerrainPoint>(),Array.Empty<int>(),0,0,0,0,Array.Empty<byte>());double InitialRoadY(RoadTerrainSource.SourceTriangle triangle,double xx,double zz,double own){return xx==b.MinX||xx==b.MaxX||zz==b.MinZ||zz==b.MaxZ?DoubleTerrainEmission.SharedHeight(own,Origins(xx,zz)):own;}var road=JoinedAsphaltBuilder.Build(c.X,c.Z,c.OriginY,context.Source,empty,c.Union.Contours,out var roadMembers,b,InitialRoadY);c.Foundation=new RoadCellFoundation(road,roadMembers,context.Dem);c.Union.Contours=c.Foundation.Contours;c.SourceKnots=c.Foundation.BoundaryPoints;c.HardKnots=c.Foundation.BoundaryPoints.Select(p=>new TerrainPoint(p.X,(float)p.Y,p.Z)).ToArray();mask=new Paths64(c.Union.Contours.Select(r=>new Path64(r.Select(p=>P(p.X,p.Z)))));target=Clipper.Difference(rect,mask,FillRule.NonZero);c.SourceKnots=c.Foundation.BoundaryPoints.Where(point=>target.Any(path=>Clipper.PointInPolygon(P(point.X,point.Z),path)==PointInPolygonResult.IsOn)).ToArray();c.HardKnots=c.SourceKnots.Select(point=>new TerrainPoint(point.X,(float)point.Y,point.Z)).ToArray();var keys=PreciseTerrainBorderKey.For(b);foreach(var key in keys){Knot(key,key.AlongMin);Knot(key,key.AlongMax);}var fine=Clipper.Intersect(target,c.Band,FillRule.NonZero);var far=Clipper.Difference(target,c.Band,FillRule.NonZero);foreach(var p in target.Concat(fine).Concat(far).SelectMany(r=>r)){double x=(double)p.X/scale,z=(double)p.Y/scale;foreach(var key in keys)if((key.Axis==0?x:z)==key.FixedWorld)Knot(key,key.Axis==0?z:x);}var dem=context.Dem;for(int i=1;i<dem.Nx-1;i++){double x=dem.MinX+i*dem.Width/(dem.Nx-1);if(x>b.MinX&&x<b.MaxX){Knot(keys[2],x);Knot(keys[3],x);}}for(int i=1;i<dem.Nz-1;i++){double z=dem.MinZ+i*dem.Depth/(dem.Nz-1);if(z>b.MinZ&&z<b.MaxZ){Knot(keys[0],z);Knot(keys[1],z);}}}catch(Exception e){c.Failure="Source/borderpreflight: "+e.Message;}}
   foreach(var pair in mandatory.OrderBy(p=>p.Key.Axis).ThenBy(p=>p.Key.FixedWorld).ThenBy(p=>p.Key.AlongMin)){cancellation.ThrowIfCancellationRequested();try{plans[pair.Key]=planner.Build(pair.Key,pair.Value.ToArray(),Sample,cancellation,Present);}catch(Exception e){foreach(var c in cells.Where(c=>PreciseTerrainBorderKey.For(c.Bounds).Contains(pair.Key)))c.Failure="Canonicalborder preflight: "+e.Message;}}
  }
  static Point64 P(double x,double z)=>new Point64((long)Math.Round(x*ManagedTerrainDomainLocal.Scale),(long)Math.Round(z*ManagedTerrainDomainLocal.Scale));
  double BorderHeight(CoreCellWork c,double x,double z){foreach(var seam in PreciseTerrainBorderKey.For(c.Bounds).Select(k=>plans[k])){if((seam.Axis==0?x:z)!=seam.FixedWorld)continue;double along=seam.Axis==0?z:x;if(along<seam.AlongOrigin||along>seam.AlongOrigin+seam.Length)continue;for(int i=1;i<seam.Count;i++){var a=seam[i-1];var b=seam[i];double aa=seam.Axis==0?a.Z:a.X,bb=seam.Axis==0?b.Z:b.X;if(along>=aa&&along<=bb)return a.Y+(along-aa)/(bb-aa)*(b.Y-a.Y);}}throw new ArgumentException("Missing canonical borderheight");}
  bool OnBorder(CoreCellWork c,double x,double z)=>x==c.Bounds.MinX||x==c.Bounds.MaxX||z==c.Bounds.MinZ||z==c.Bounds.MaxZ;
  public VerifiedJoinedTerrain BuildCell(CoreCellWork c,CancellationToken cancellation=default){if(c.Failure!=null)throw new ArgumentException(c.Failure);var b=c.Bounds;var seams=PreciseTerrainBorderKey.For(b).Select(k=>plans[k]).ToArray();var collar=new CanonicalSeamCollar(b.MinX,b.MinZ,seams,Raw,Present);double Emit(double x,double z,double original){if(OnBorder(c,x,z))return BorderHeight(c,x,z);if(context.Source.Pavement(x,z,out _,out _,out _))return c.Foundation.BoundaryHeight(x,z);return original;}
   var domain=ManagedTerrainDomainLocal.Build(c.X,c.Z,c.Union.Contours,c.SourceKnots,seams,context.Dem,collar.World,token:cancellation,exposedGroundKnots:c.HardKnots,explicitBounds:b,protectedBandOverride:c.Band);var initial=domain.Vertices.Select(p=>{double x=b.MinX+p.X,z=b.MinZ+p.Z;return new TerrainPoint(p.X,(float)(Emit(x,z,collar.World(x,z).Y)-c.OriginY),p.Z);}).ToArray();TerrainMeshSample Target(double x,double z){var s=collar.World(b.MinX+x,b.MinZ+z);return new TerrainMeshSample(s.Y-c.OriginY,s.SourceDistance,s.Authority);}TerrainMeshSample Emission(double x,double z){var s=Target(x,z);return new TerrainMeshSample(Emit(b.MinX+x,b.MinZ+z,s.Y+c.OriginY)-c.OriginY,s.SourceDistance,s.Authority);}var classify=new ProtectedBandClassifier(c.Band,(long)Math.Round(b.MinX*ManagedTerrainDomainLocal.Scale),(long)Math.Round(b.MinZ*ManagedTerrainDomainLocal.Scale));var mesh=ManagedAdaptiveMesh.Build(initial,domain.Triangles,domain.Constraints,Target,new TerrainMeshLimits{WallSeconds=20,Vertices=24000,Faces=48000,Queries=150000,Work=600000,TotalFlips=150000,FlipsPerCall=16384},cancellation,domain.Density,classify.Classify,Emission,bank,b.MinX,b.MinZ);var boundaryCounts=new Dictionary<TerrainMeshEdge,int>();for(int i=0;i<mesh.Triangles.Length;i+=3){int a=mesh.Triangles[i],bb=mesh.Triangles[i+1],cc=mesh.Triangles[i+2];foreach(var edge in new[]{new TerrainMeshEdge(a,bb),new TerrainMeshEdge(bb,cc),new TerrainMeshEdge(cc,a)}){boundaryCounts.TryGetValue(edge,out int n);boundaryCounts[edge]=n+1;}}long scale=ManagedTerrainDomainLocal.Scale;var terrainBoundary=new Dictionary<(long,long),double>();foreach(var pair in boundaryCounts.Where(p=>p.Value==1))foreach(int id in new[]{pair.Key.A,pair.Key.B}){var point=mesh.Vertices[id];terrainBoundary[((long)Math.Round((b.MinX+point.X)*scale),(long)Math.Round((b.MinZ+point.Z)*scale))]=c.OriginY+point.Y;}double RoadY(RoadTerrainSource.SourceTriangle triangle,double x,double z,double own){return terrainBoundary.TryGetValue(((long)Math.Round(x*scale),(long)Math.Round(z*scale)),out double targetY)?targetY:own;}
   LocalTerrainMesh[] roads;Dictionary<string,string[]> members;if(c.Foundation.Geometry==null){roads=Array.Empty<LocalTerrainMesh>();members=new Dictionary<string,string[]>();}else{var intermediate=JoinedAsphaltBuilder.Build(c.X,c.Z,c.OriginY,c.Foundation.Geometry,mesh,c.Union.Contours,out var intermediateMembers,b,RoadY,composeFlatOwners:false);members=new Dictionary<string,string[]>();roads=intermediate.Select(p=>{string root=p.Id.Substring(0,p.Id.IndexOf("/cell/",StringComparison.Ordinal)),id=root+"/cell/"+c.X+"/"+c.Z;members[id]=intermediateMembers[p.Id];return new LocalTerrainMesh(id,p.OriginX,p.OriginY,p.OriginZ,p.XYZ,p.Indices);}).ToArray();}
   var terrain=new LocalTerrainMesh("terrain/cell/"+c.X+"/"+c.Z,b.MinX,c.OriginY,b.MinZ,mesh.Vertices.SelectMany(p=>new[]{(float)p.X,(float)p.Y,(float)p.Z}).ToArray(),mesh.Triangles);return VerifiedJoinedTerrain.VerifyExplicitCandidate(context.SourceDigest,context.RawDocumentDigest,context.DemInputDigest,context.ControlDigest,context.StructureLedgerDigest,b,context.Source,roads,(terrain.Indices.Length==0?Array.Empty<LocalTerrainMesh>():new[]{terrain}),members,context.Frames,cancellation,bank);
  }
  public bool RefineBorder(CoreCellWork c,TerrainSeamRefinementRequired e,CancellationToken cancellation=default){int axis=e.A.X==e.B.X?0:1;double fixedWorld=axis==0?c.Bounds.MinX+e.A.X:c.Bounds.MinZ+e.A.Z;var key=PreciseTerrainBorderKey.For(c.Bounds).Single(k=>k.Axis==axis&&k.FixedWorld==fixedWorld);mandatory[key].Add(axis==0?c.Bounds.MinZ+e.NewKnot.Z:c.Bounds.MinX+e.NewKnot.X);plans[key]=planner.Build(key,mandatory[key].ToArray(),Sample,cancellation,Present);foreach(var neighbor in cells.Where(n=>PreciseTerrainBorderKey.For(n.Bounds).Contains(key)))neighbor.Proof=null;return true;}
 }
